import{_ as e,o,c as d,a2 as a}from"./chunks/framework.BXzK3EA4.js";const _=JSON.parse('{"title":"模型配置","description":"","frontmatter":{"title":"模型配置"},"headers":[],"relativePath":"app-center/openclaw/model-config.md","filePath":"app-center/openclaw/model-config.md","lastUpdated":1794381603000}'),r={name:"app-center/openclaw/model-config.md"};function c(n,t,p,i,l,s){return o(),d("div",null,[...t[0]||(t[0]=[a('<blockquote><p><strong>说明</strong></p><p>模型配置为可选项。部署时预填可让应用开箱即用；若部署时留空，安装完成后也可通过管理控制台或 CLI 随时补充。</p></blockquote><h3 id="方式一-部署时预配置" tabindex="-1">方式一：部署时预配置 <a class="header-anchor" href="#方式一-部署时预配置" aria-label="Permalink to &quot;方式一：部署时预配置&quot;">​</a></h3><p>在应用部署参数页面的高级参数（默认折叠）中填写以下字段，仅填写需要的项，留空则不启用。</p><p><strong>原生供应商 API Key</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>openai_api_key</code></td><td>OpenAI API Key</td><td><code>sk-...</code></td></tr><tr><td><code>anthropic_api_key</code></td><td>Anthropic API Key</td><td><code>sk-ant-...</code></td></tr><tr><td><code>google_api_key</code></td><td>Google Gemini API Key</td><td><code>AIza...</code></td></tr></tbody></table><p><strong>OpenAI 兼容接口</strong>（如阿里云百炼、DeepSeek、Moonshot 等，以下三项需同时填写）</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>compat_base_url</code></td><td>兼容接口的 Base URL</td><td><code>https://dashscope.aliyuncs.com/compatible-mode/v1</code></td></tr><tr><td><code>compat_api_key</code></td><td>对应服务的 API Key</td><td><code>sk-xxxxx</code></td></tr><tr><td><code>compat_provider_name</code></td><td>自定义 provider 名称（即后续模型的前缀）</td><td><code>bailian</code></td></tr></tbody></table><p><strong>默认模型</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>default_model</code></td><td>格式为 <code>&lt;provider&gt;/&lt;model-id&gt;</code></td><td><code>openai/gpt-4o</code>、<code>bailian/qwen3-max</code></td></tr></tbody></table><h3 id="方式二-部署后通过-cli-配置-进阶" tabindex="-1">方式二：部署后通过 CLI 配置（进阶） <a class="header-anchor" href="#方式二-部署后通过-cli-配置-进阶" aria-label="Permalink to &quot;方式二：部署后通过 CLI 配置（进阶）&quot;">​</a></h3><p>具体步骤参见本章“模型配置指引”。</p><h3 id="方式三-部署后通过管理控制台配置" tabindex="-1">方式三：部署后通过管理控制台配置 <a class="header-anchor" href="#方式三-部署后通过管理控制台配置" aria-label="Permalink to &quot;方式三：部署后通过管理控制台配置&quot;">​</a></h3><p>访问 Web 控制台（<code>http://[您的服务器IP]:[gateway_port]</code>），登录后进入 <strong>AI Model Configurations and Providers</strong> 配置页面，添加所需的 provider 及 API Key。</p><blockquote><p><strong>提示</strong></p><p>OpenAI、Anthropic、Google Gemini 等主流 provider 无需额外配置，只需填入对应 API Key 即可直接使用。对于阿里云百炼、DeepSeek、Moonshot 等 OpenAI 兼容接口，需同时填写 Base URL、API Key 和 Provider 名称。详见 <a href="https://docs.openclaw.ai/concepts/model-providers" target="_blank" rel="noreferrer">Model Providers 文档</a>。</p></blockquote>',14)])])}const b=e(r,[["render",c]]);export{_ as __pageData,b as default};
